// گام ۱ — بررسی توکن و تکه‌تکه‌کردن متن سند.
// متن پیشنهاد معمولاً از پنجره‌ی ورودی مدل‌های محلی بزرگ‌تر است؛ پس آن را به چند «تکه» با
// هم‌پوشانی می‌شکنیم و هر تکه را جدا از مدل می‌پرسیم (الگوی map-reduce).
const req = $input.first().json;
if (!$env.AGENT_TOKEN || (req.headers || {})['x-agent-token'] !== $env.AGENT_TOKEN) {
  throw new Error('Unauthorized: invalid X-Agent-Token');
}
const body = req.body || {};
const text = String((body.document || {}).text || '');
const checklist = Array.isArray(body.checklist) ? body.checklist : [];
const SIZE = Number($env.VALIDATION_WINDOW_CHARS) || 4000;
const OVERLAP = 500;

const windows = [];
for (let start = 0; start < text.length; start += SIZE - OVERLAP) {
  windows.push(text.slice(start, start + SIZE));
  if (start + SIZE >= text.length) break;
}

const list = checklist
  .map((i) => `- ${i.key} (${i.group === 'field' ? 'فیلد' : 'بخش'}): ${i.label} — ${i.hint}`)
  .join('\n');

const system = [
  'تو دستیار بررسی «قالب» فرم پیشنهاد پروژه‌ی کارشناسی دانشکده‌ی مهندسی کامپیوتر دانشگاه صنعتی امیرکبیر هستی.',
  'ورودی: فهرست موارد الزامی فرم و «یک تکه» از متن استخراج‌شده‌ی سند.',
  'وظیفه: مشخص کن کدام موارد فهرست در «همین تکه» وجود دارند.',
  'قواعد:',
  '۱. یک «بخش» فقط وقتی وجود دارد که عنوان آن (یا عنوانی هم‌معنا) در متن آمده و زیر آن دست‌کم یک جمله محتوا نوشته شده باشد.',
  '۲. یک «فیلد» فقط وقتی وجود دارد که مقدارش پر شده باشد؛ برچسبِ بدون مقدار یعنی خالی.',
  '۳. برای هر مورد یافت‌شده، evidence را عیناً و بدون هیچ تغییری از متن رونویسی کن (حداکثر ۱۲ واژه).',
  '۴. درباره‌ی کیفیت علمی نظر نده و حدس نزن؛ اگر مطمئن نیستی آن مورد را نیاور.',
  'خروجی فقط یک شیء JSON با همین شکل باشد و هیچ متن دیگری ننویس:',
  '{"found": [{"key": "<کلید مورد>", "evidence": "<نقل‌قول عینی از متن>"}]}',
].join('\n');

return windows.map((windowText, index) => ({
  json: {
    validation_id: body.validation_id,
    window_index: index,
    window_count: windows.length,
    window_text: windowText,
    keys: checklist.map((i) => i.key),
    llm_request: {
      model: $env.LLM_CHAT_MODEL,
      temperature: 0,
      stream: false,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        {
          role: 'user',
          content: `موارد الزامی:\n${list}\n\nمتن سند (تکه‌ی ${index + 1} از ${windows.length}):\n"""\n${windowText}\n"""`,
        },
      ],
    },
  },
}));

// گام ۳ — تجمیع پاسخ تکه‌ها و «راستی‌آزمایی شاهد».
// مدل برای هر مورد باید نقل‌قولی از متن بیاورد؛ اگر آن نقل‌قول واقعاً در همان تکه نباشد،
// ادعای مدل پذیرفته نمی‌شود (کاهش خطای توهم مدل زبانی).
const windows = $('Split Into Windows').all();
const responses = $input.all();

const FA_DIGITS = '۰۱۲۳۴۵۶۷۸۹';
const norm = (s) =>
  String(s || '')
    .normalize('NFKC')
    .replace(/[\u200c\u200e\u200f\u0640\u064b-\u065f]/g, '')
    .replace(/[يى]/g, 'ی')
    .replace(/ك/g, 'ک')
    .replace(/[۰-۹]/g, (d) => String(FA_DIGITS.indexOf(d)))
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim()
    .toLowerCase();

function supported(evidence, windowText) {
  const e = norm(evidence);
  if (e.length < 3) return false;
  const w = norm(windowText);
  if (w.includes(e)) return true;
  const have = new Set(w.split(' '));
  const words = e.split(' ').filter((x) => x.length >= 2);
  if (!words.length) return false;
  return words.filter((x) => have.has(x)).length / words.length >= 0.7;
}

function parseJson(content) {
  const clean = String(content).replace(/<think>[\s\S]*?<\/think>/g, '');
  const start = clean.indexOf('{');
  const end = clean.lastIndexOf('}');
  if (start < 0 || end <= start) throw new Error('no JSON object');
  return JSON.parse(clean.slice(start, end + 1));
}

const found = {};
const unverified = {};
let failed = 0;
let lastError = '';

responses.forEach((item, i) => {
  const w = windows[i].json;
  const res = item.json || {};
  const content = res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
  let parsed = null;
  if (content) {
    try {
      parsed = parseJson(content);
    } catch (e) {
      lastError = 'خروجی مدل JSON معتبر نبود';
    }
  } else {
    const err = res.error;
    lastError = (err && (err.message || (typeof err === 'string' ? err : JSON.stringify(err)))) || 'پاسخ خالی از مدل';
  }
  if (!parsed || !Array.isArray(parsed.found)) {
    failed += 1;
    return;
  }
  for (const f of parsed.found) {
    if (!f || !w.keys.includes(f.key)) continue;
    const row = { key: f.key, evidence: String(f.evidence || '').slice(0, 200), window: i + 1 };
    if (supported(f.evidence, w.window_text)) {
      if (!found[f.key]) found[f.key] = row;
    } else if (!unverified[f.key]) {
      unverified[f.key] = row;
    }
  }
});

const model = $env.LLM_CHAT_MODEL;
const result =
  failed === windows.length
    ? { error: 'مدل زبانی پاسخ قابل‌استفاده‌ای نداد.', detail: String(lastError).slice(0, 300), model }
    : {
        found: Object.values(found),
        unverified: Object.values(unverified).filter((u) => !found[u.key]),
        windows: windows.length,
        failed_windows: failed,
        model,
      };

return [{ json: { validation_id: windows[0].json.validation_id, result } }];
